const e={"home.about.card.list.0":"தயாரிப்பு திசை ஆராய்ச்சி மற்றும் அங்கீகாரம் (நடப்பு)","home.about.card.list.1":"முக்கிய திறனை மேம்படுத்துதல்: பொறியியல் அமைப்பு / தரவுகள் மற்றும் சேவை திறன்கள் / அடிப்படையியல்","home.about.card.list.2":"மாதிரியாக்கம் மற்றும் விரைவு முறைமைகள்: யோசனை முதல் பயன்பாட்டுக்கூடிய பதிப்பு","home.about.card.list.3":"அனுமதி மற்றும் பாதுகாப்பு: தரவுப் பாதுகாப்பும் தனியுரிமை பாதுகாப்பும் மீது முக்கியத்துவம்","home.about.card.note":"வணிகத்தின் பரப்பளவு இன்னும் ஆராய்ச்சி நிலைமையில் உள்ளது...","home.about.card.title":"நாம் என்ன செய்கிறோம்?","home.about.desc.0":"நாங்கள் சுய ஆராய்ச்சியில் கவனம் செலுத்தும் நெட்வொர்க் தொழில்நுட்ப நிறுவனம்...","home.about.desc.1":"தற்போதைய வணிக வரம்பு இன்னும் தொடர்ந்த ஆராய்ச்சியில் உள்ளது...","home.about.hl.0.num":"சுயமாக உருவாக்கப்பட்ட முதல்","home.about.hl.0.text":"தன் சொந்த தயாரிப்புகள் மற்றும் வணிகத்தில் தொடர்ந்த முதலீடு.","home.about.hl.1.num":"தொடர்ச்சியான திருத்தம்","home.about.hl.1.text":"இயந்திரக் குவாலிட்டி, பராமரிப்பு மற்றும் அளவீட்டிற்கு முக்கியத்துவம் அளிக்கவும்.","home.about.hl.2.num":"தொடர்ந்து ஆராய்ந்து கொண்டிருக்கிறோம்","home.about.hl.2.text":"வணிகத் திசைகளின் இயக்கவியல் வளர்ச்சி மெதுவாக தெளிவான எல்லைகளை உருவாக்குகிறது.","home.about.title":"எங்களைப் பற்றி","home.brand.en":"TreeHouse Tech · Shanghai","home.common.city":"ஷாங்காய் · SHANGHAI","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"நாங்கள் தொடர்புகொள்வதற்காக, தயவுசெய்து மின்னஞ்சல் மூலம் தொடர்புகொள்ளவும்...","home.contact.label.city":"நகரம்","home.contact.label.company":"கம்பெனி பெயர்","home.contact.label.email":"மின்னஞ்சல்","home.contact.title":"தொடர்பு தகவல்","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"எங்களைப் பற்றி","home.footer.links.contact":"எங்களை தொடர்பு கொள்ளவும்","home.footer.links.home":"முகப்பு","home.footer.slogan":"சுயமாக ஆராய்ச்சி மற்றும் வளர்ச்சியில் கவனம் செலுத்துங்கள் · தொடர்ந்த ஆராய்ச்சி · நிலையான மாறுபாடு","home.hero.cta.about":"எங்களைப் பற்றி மேலும் அறிக","home.hero.cta.contact":"தொடர்பு தகவல்","home.hero.desc":"நாங்கள் சுய ஆராய்ச்சியில் கவனம் செலுத்தும் நெட்வொர்க் தொழில்நுட்ப நிறுவனம். நாங்கள் மதிப்புமிக்க தயாரிப்பு திசைகளை மற்றும் தொழில்நுட்ப செயலாக்க பாதைகளை தொடர்ந்து ஆராய்கிறோம், நீண்ட கால மறு திருத்தம் மற்றும் நிலையான வழங்கலுக்காக நோக்கமாகக் கொண்டுள்ளோம்.","home.hero.glass":'திசை ஆராய்ச்சி → பொறியியல் செயலாக்கம் → தயாரிப்பு மேம்பாடு <span class="dot"></span> நீண்டகாலம் / நிலையான வழங்கல்',"home.hero.meta.0.label":"தயாரிப்பு மற்றும் பொறியியல் மையமாக","home.hero.meta.0.num":"சுயமாக உருவாக்கப்பட்டது","home.hero.meta.1.label":"தொடர்ச்சியான திருத்தம் மற்றும் மேம்பாடு","home.hero.meta.1.num":"நீண்ட காலம்","home.hero.meta.2.label":"தரமும் ஒத்துழைப்பும் முக்கியத்துவம்","home.hero.meta.2.num":"திடமாக","home.hero.mini.foot":"* தற்போதைய அதிகாரப்பூர்வ வலைத்தளம் ஒரு அடிப்படை அறிமுகப் பக்கம் ஆகும், மற்றும் உள்ளடக்கம் வணிகம் முன்னேறுவதற்கேற்ப தொடர்ந்து புதுப்பிக்கப்படும்.","home.hero.mini.head":"குறிப்பு","home.hero.mini.main":"தொடர்ந்து வணிக திசைகளை ஆராய்ந்து கொண்டிருக்கிறோம்","home.hero.mini.stats.0.k":"மையம்","home.hero.mini.stats.0.v":"சுயமாக உருவாக்கப்பட்ட தயாரிப்பு","home.hero.mini.stats.1.k":"வடிவம்","home.hero.mini.stats.1.v":"மெதுவாக தெளிவுபடுத்தவும்","home.hero.mini.stats.2.k":"இசை","home.hero.mini.stats.2.v":"மறுபடியும் முன்னேற்றம்","home.hero.mini.stats.3.k":"இலக்கு","home.hero.mini.stats.3.v":"திடமான வளர்ச்சி","home.hero.title":'<span class="accent"> சுயாதீன ஆராய்ச்சி மற்றும் வளர்ச்சி </span> மற்றும் தயாரிப்பு ஆராய்ச்சி மீது கவனம் செலுத்துதல்',"home.html.lang":"ta","home.meta.description":"上海树下小屋网络科技有限公司 - சுயமாக ஆராய்ச்சி மற்றும் தயாரிப்பு ஆராய்ச்சியில் கவனம் செலுத்துகிறது","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"எங்களைப் பற்றி","home.nav.contact":"எங்களை தொடர்பு கொள்ளவும்","home.nav.home":"முகப்பு","home.nav.toggle":"மெனுவை விரிவாக்கவும்","home.noscript":"இந்த தளம் முழுமையான இடைமுக அனுபவத்திற்காக JavaScript ஐ தேவைப்படுகிறது (இயக்க மெனு, உருட்டும் விளைவுகள், மற்றும் பிற).","nav.apps":"ஆப் மையம்","nav.support":"ஆதரவு","apps.hero.eyebrow":"sxxw.site · ஆப் ஆதரவு மையம்","apps.hero.title":"ஒவ்வொரு ஆப்பும் தெளிவான வழிகாட்டுதலோடும், நீங்கள் கட்டுப்படுத்தும் தரவு எல்லைகளோடும் வருகிறது.","apps.hero.desc":"இங்கே தயாரிப்பு அறிமுகம், தொடக்க வழிகாட்டிகள், தனியுரிமைக் கொள்கை, விதிமுறைகள், தொழில்நுட்ப ஆதரவு ஆகியவற்றைக் காணலாம். நீங்கள் உண்மையில் பயன்படுத்தும் தளத்திற்கான பகுதியைப் படியுங்கள்.","apps.card.cta":"ஆப்பைப் பார்","apps.memoria.desc":"பிறந்தநாள்கள், ஆண்டுவிழாக்கள், கவுண்ட்டவுன்களைக் கண்காணியுங்கள். iOS பதிப்பு விருப்பத் தேர்வான தனிப்பட்ட iCloud ஒத்திசைவை ஆதரிக்கிறது; Huawei AppGallery-யின் Memoria பதிப்பு முழுவதுமாக சாதனத்திலேயே இயங்குகிறது.","apps.memoria.tag":"ஆண்டுவிழாக்கள் · நினைவூட்டல்கள்","apps.timetrails.desc":"தனியுரிமை-முதன்மை GPS பாதைப் பதிவு: பயணங்கள், உடற்பயிற்சிகள், சுற்றுலாக்களைத் தானாகப் பதிவு செய்கிறது, வரைபடத்தில் உங்கள் காலடித் தடங்களை வரைந்து, நீங்கள் சென்ற நகரங்களை ஒளிரச் செய்கிறது. பாதைகள் இயல்பாகச் சாதனத்திலேயே இருக்கும், விருப்பத் தேர்வான தனிப்பட்ட iCloud காப்புடன்.","apps.timetrails.tag":"GPS பாதைகள் · வழிகள்","apps.traceapp.desc":"பாதை, தூரம், வேகம், வேகக் கதி ஆகியவற்றைப் பதிவு செய்கிறது. கணக்கு இல்லை, உள்ளமைந்த விளம்பரங்களோ மூன்றாம் தரப்பு பகுப்பாய்வுகளோ இல்லை.","apps.traceapp.tag":"வழிகள் · புள்ளிவிவரம்","apps.footer.slogan":"தயாரிப்புகள் · வழிகாட்டிகள் · தனியுரிமை மற்றும் ஆதரவு","support.brand":"ஆதரவு","support.hero.eyebrow":"sxxw.site · ஆதரவு மையம்","support.hero.title":"உங்களுக்கு ஏற்ற வழியில் TreeHouse-ஐ தொடர்பு கொள்ளுங்கள்.","support.hero.desc":"TreeHouse ஆப்களுக்கான அனைத்து அதிகாரப்பூர்வ ஆதரவு சேனல்களும் ஒரே இடத்தில்: கருத்து, ஆப்-ஸ்டோர் மதிப்புரைகள், அதிகாரப்பூர்வ சமூகக் குழுக்கள். லோக்கல்-ஃபர்ஸ்ட், விளம்பரங்கள் இல்லை, மூன்றாம் தரப்பு கண்காணிப்பு இல்லை.","support.g1.title":"கருத்து","support.g1.note":"சிக்கல் ஏற்பட்டதா அல்லது யோசனை உள்ளதா? கீழேயுள்ள எந்த வழியிலும் எங்களைத் தொடர்பு கொள்ளுங்கள் — ஒவ்வொரு செய்தியையும் நாங்கள் படிக்கிறோம்.","support.g1.feedback.name":"ஆப்பினுள் கருத்து","support.g1.feedback.desc":"ஒவ்வொரு ஆப்பினுள்ளிருந்தே அனுப்புங்கள்; உங்கள் பதிப்பு, சாதனம், அமைப்புத் தகவல் தானாகவே இணைக்கப்படும், அதனால் நாங்கள் விரைவாக ஆராயலாம்.","support.g1.feedback.cta":"ஆப்களைப் பார்","support.g1.email.name":"மின்னஞ்சல் அனுப்பு","support.g1.email.desc":"முறையான கோரிக்கைகளுக்கும், தனியுரிமை அல்லது கணக்கு தொடர்பான விஷயங்களுக்கும் மின்னஞ்சலில் முழுமையான பதில் கிடைக்கும்.","support.g1.email.cta":"மின்னஞ்சல் அனுப்பு","support.g2.title":"ஆப்களை மதிப்பிடுங்கள் (ஒவ்வொரு ஆப்பிற்கும்)","support.g2.note":"பிடித்திருந்தால் நீங்கள் பயன்படுத்தும் ஸ்டோரில் மதிப்புரை எழுதுங்கள் — நாங்கள் பார்த்துப் பதிலளிக்கிறோம். உங்கள் ஆப்பிற்குப் பொருந்துவதைத் தட்டுங்கள்.","support.g2.cta.write":"மதிப்புரை எழுது","support.g2.cta.goto":"மதிப்புரைக்குச் செல்","support.g2.memoria.huawei.platform":"HarmonyOS · Huawei சாதனங்கள்","support.g3.title":"WeChat · QQ · Telegram குழுக்கள்","support.g3.note":"புதுப்பிப்புகளுக்கும் சக-பயனர்களின் உதவிக்கும் எங்கள் அதிகாரப்பூர்வ குழுக்களில் இணையுங்கள்: சீனாவில் WeChat / QQ, மற்ற இடங்களில் Telegram.","support.g3.wechat.name":"WeChat குழு","support.g3.wechat.desc":"தினசரி அரட்டையும் உதவியும். குழு நிரம்பும்போது புதிய QR குறியீடு வெளியிடப்படும்.","support.g3.qq.name":"QQ குழு","support.g3.qq.desc":"சீனாவில் உள்ள பயனர்களுக்கு; அதிக உறுப்பினர் வரம்பு.","support.g3.tg.name":"Telegram குழு","support.g3.tg.desc":"சர்வதேச பயனர்களுக்கான அரட்டையும் கேள்வி-பதிலும்.","support.g3.join":"இணை","support.pending":"விரைவில்","support.foot":"சரியான சேனலைக் கண்டறிய முடியவில்லையா? house@sxxw.site-க்கு மின்னஞ்சல் அனுப்புங்கள், நாங்கள் பதிலளிப்போம்.","support.footer.slogan":"கருத்து · ஆப்-ஸ்டோர் மதிப்புரைகள் · சமூகக் குழுக்கள்","mem.ios.tagline":"பிறந்தநாள், ஆண்டுவிழா, முக்கிய நாட்களைப் பதிவு செய்யுங்கள், நேரத்தை மென்மையாகக் காணுங்கள்.","mem.ios.desc":"பிறந்தநாள், ஆண்டுவிழா, காதல் ஆண்டுவிழா, பண்டிகைகள், உங்களுக்குப் பிரியமான நாட்களை ஒரே அமைதியான இடத்தில் வையுங்கள். பின்னோக்கி எண்ணி இன்னும் எத்தனை நாட்கள் என்று பாருங்கள், முன்னோக்கி எண்ணி எத்தனை நாட்கள் கடந்தது என்று சேமியுங்கள்.","mem.ios.feat.0":"பிறந்தநாள், ஆண்டுவிழா, பண்டிகை மற்றும் தனிப்பயன் நிகழ்வுகள்","mem.ios.feat.1":"கிரிகோரியன் மற்றும் சீன சந்திர தேதிகள்","mem.ios.feat.2":"பின்னோக்கி எண்ணல், முன்னோக்கி எண்ணல் மற்றும் வாழ்க்கை முன்னேற்றம்","mem.ios.feat.3":"உள்ளூர் நினைவூட்டல்கள், முகப்புத் திரை மற்றும் பூட்டுத் திரை விட்ஜெட்கள்","mem.ios.feat.4":"Apple Watch-இல் விரைவுப் பார்வை","mem.ios.feat.5":"விருப்பத் தேர்வு iCloud தனிப்பட்ட ஒத்திசைவு","mem.ios.guide.0.t":"முதல் பதிவை உருவாக்குங்கள்","mem.ios.guide.0.b":"பயன்பாட்டைத் திறந்து சேர் என்பதைத் தேர்ந்தெடுத்து, பெயர், தேதி, சேமிக்க விரும்பும் குறிப்பை நிரப்புங்கள். தேவைக்கேற்ப பிறந்தநாள், ஆண்டுவிழா, பண்டிகை அல்லது தனிப்பயன் நிகழ்வைத் தேர்ந்தெடுங்கள்.","mem.ios.guide.1.t":"தேதி விதியைத் தேர்ந்தெடுங்கள்","mem.ios.guide.1.b":"பிறந்தநாள் மற்றும் ஆண்டுவிழாவுக்கு கிரிகோரியன் அல்லது சீன சந்திர நாட்காட்டியைப் பயன்படுத்தலாம். சந்திரப் பதிவுகள் விதிப்படி அடுத்த தேதியைக் கணக்கிட்டுக் காட்டும்.","mem.ios.guide.2.t":"நினைவூட்டலை அமையுங்கள்","mem.ios.guide.2.b":"முக்கிய நாட்களுக்கு உள்ளூர் அறிவிப்பை இயக்கி, அன்றே அல்லது முன்கூட்டியே நினைவூட்டல் நேரத்தைத் தேர்ந்தெடுங்கள். அறிவிப்பு அனுமதி முடக்கப்பட்டால், அதை இயக்க கணினி அமைப்புகளுக்குச் செல்லுமாறு பயன்பாடு அறிவுறுத்தும்.","mem.ios.guide.3.t":"தேவைக்கேற்ப ஒத்திசைவை இயக்குங்கள்","mem.ios.guide.3.b":"உங்கள் iPhone, iPad மற்றும் Apple Watch இடையே ஒத்திசைக்க வேண்டுமெனில், iCloud-இல் உள்நுழைந்திருக்கும்போது ஒத்திசைவை இயக்குங்கள். தரவு உங்கள் CloudKit தனிப்பட்ட தரவுத்தளத்திற்குச் செல்கிறது, டெவலப்பர் அதைப் படிக்க முடியாது.","mem.hm.tagline":"பிறந்தநாள், ஆண்டுவிழா, முக்கிய நாட்களைச் சாதனத்திலேயே உள்ளூராகப் பதிவு செய்யுங்கள்.","mem.hm.desc":"拾忆 என்பது HarmonyOS தளத்தில் Memoria · 拾忆 இன் உள்ளூர் பதிப்பாகும். கணக்கு இல்லை, இணையம் இல்லை, கிளவுட் ஒத்திசைவு இல்லை; தரவு உங்கள் சாதனத்தின் பயன்பாட்டு சாண்ட்பாக்ஸில் மட்டுமே சேமிக்கப்படுகிறது.","mem.hm.feat.0":"பிறந்தநாள், ஆண்டுவிழா, பண்டிகை மற்றும் தனிப்பயன் நிகழ்வுகள்","mem.hm.feat.1":"கிரிகோரியன் மற்றும் சீன சந்திர தேதிகள்","mem.hm.feat.2":"பின்னோக்கி எண்ணல், முன்னோக்கி எண்ணல் மற்றும் வாழ்க்கை முன்னேற்றம்","mem.hm.feat.3":"உள்ளூர் நினைவூட்டல்கள்","mem.hm.feat.4":"மறுசுழற்சி தொட்டியிலிருந்து மீட்பு மற்றும் முழுமையாக நீக்கல்","mem.hm.feat.5":"கணக்கு இல்லை, விளம்பரம் இல்லை, நெட்வொர்க் கோரிக்கை இல்லை","mem.hm.guide.0.t":"புதிய ஆண்டுவிழாவைச் சேருங்கள்","mem.hm.guide.0.b":"ஆண்டுவிழா பக்கத்திற்குச் சென்று புதியதை உருவாக்கு என்பதைத் தேர்ந்தெடுத்து, பெயர், தேதி, வகை மற்றும் குறிப்பை நிரப்புங்கள். தேவைப்பட்டால் சீன சந்திர தேதியைத் தேர்ந்தெடுக்கலாம்.","mem.hm.guide.1.t":"அடுத்த தேதியை உறுதிப்படுத்துங்கள்","mem.hm.guide.1.b":"சேமித்த பிறகு, தேதி மற்றும் மீள்திரும்பல் விதிப்படி அடுத்த தேதியைப் பயன்பாடு காட்டும். சந்திரப் பதிவுகள் தொடர்புடைய விதிப்படி மாற்றப்படும்.","mem.hm.guide.2.t":"உள்ளூர் நினைவூட்டலை அமையுங்கள்","mem.hm.guide.2.b":"பதிவில் நினைவூட்டல் நேரத்தையும் எத்தனை நாட்களுக்கு முன் தெரிவிக்க வேண்டும் என்பதையும் தேர்ந்தெடுங்கள். முதல் முறை நினைவூட்டலை அமைக்கும்போது கணினி அறிவிப்புக்கு அனுமதி அளியுங்கள்; அனுமதி முடக்கப்பட்டால் நினைவூட்டலை மட்டுமே பாதிக்கும், பதிவையோ பார்வையையோ அல்ல.","mem.hm.guide.3.t":"உள்ளூர் தரவை நிர்வகியுங்கள்","mem.hm.guide.3.b":"நீக்கப்பட்ட பதிவுகள் முதலில் மறுசுழற்சி தொட்டிக்குச் செல்லும், அங்கிருந்து மீட்கலாம் அல்லது முழுமையாக நீக்கலாம். பயன்பாட்டை நிறுவல் நீக்கினால் சாதனத்தின் பயன்பாட்டுத் தரவு அழியும்; கிளவுட் காப்பு இல்லாததால் சாதனத்தை மாற்றியபின்னோ நிறுவல் நீக்கியபின்னோ மீட்க முடியாது.","tt.tagline":"GPS தட பதிவு, நடந்த பாதை உங்கள் சொந்த நேரத்தில் இருக்கட்டும்.","tt.desc":"时光轨迹 TimeTrails என்பது தனியுரிமை-முதன்மை GPS தட பதிவுப் பயன்பாடு. பயணம், ஓட்டம், சைக்கிள், நடைப்பயணம், வாகனம் ஓட்டுதல் ஆகியவற்றின் பாதைகளைத் தானாகப் பதிவு செய்து, வரைபடத்தில் உங்கள் காலடித் தடங்களை உயிர்ப்புடன் காட்டி, சென்ற நகரங்களை ஒளிரச் செய்கிறது. கணக்குப் பதிவு தேவையில்லை, விளம்பரமோ மூன்றாம் தரப்பு கண்காணிப்போ இல்லை, தட தரவு இயல்பாக உங்கள் சாதனத்தில் மட்டுமே சேமிக்கப்படுகிறது.","tt.feat.0":"தினசரி நடமாட்டப் பாதைகளையும் தூரத்தையும் தானாகப் பதிவு செய்யுங்கள்","tt.feat.1":"உள்ளூர் நேரப்படி தினசரிப் பாதையும் செயல்பாட்டுச் சுருக்கமும்","tt.feat.2":"மூடுபனி ஆய்வால் சென்ற இடங்களை மீண்டும் காணுங்கள்","tt.feat.3":"நடத்தல், சைக்கிள், வாகனம் போன்ற செயல்பாட்டு வகைகளை அடையாளம் காணுங்கள்","tt.feat.4":"பாதையின் நினைவைப் பேண விருப்பத் தேர்வு புகைப்பட இறக்குமதி","tt.feat.5":"விருப்பத் தேர்வு iCloud தனிப்பட்ட தரவுத்தள காப்பு மற்றும் சாதன மாற்றத்தில் மீட்பு","tt.guide.0.t":"இருப்பிட அனுமதியைத் தேர்ந்தெடுங்கள்","tt.guide.0.b":'பின்னணியில் தொடர்ச்சியான பதிவுக்கு, கணினி அறிவிப்பில் "எப்போதும்" இருப்பிடத்தையும் "துல்லிய இருப்பிடத்தையும்" அனுமதியுங்கள். எப்போது வேண்டுமானாலும் கணினி அமைப்புகளில் மாற்றலாம்.',"tt.guide.1.t":"பதிவைத் தொடங்குங்கள்","tt.guide.1.b":"முதல் முறை நுழைந்து பதிவை இயக்குங்கள். பயன்பாட்டில் எப்போது வேண்டுமானாலும் இடைநிறுத்தலாம் அல்லது மீண்டும் தொடங்கலாம், கட்டுப்பாடு உங்கள் கையில்.","tt.guide.2.t":"தினசரிப் பாதையைப் பாருங்கள்","tt.guide.2.b":"நாட்காட்டி அல்லது வரைபடத்தில் ஒவ்வொரு நாளின் பாதை, தூரம், நிறுத்தங்கள் மற்றும் செயல்பாட்டுச் சுருக்கத்தைப் பாருங்கள்.","tt.guide.3.t":"தேவைக்கேற்ப காப்பை இயக்குங்கள்","tt.guide.3.b":"சாதன மாற்றத்தில் மீட்பு அல்லது பல சாதன ஒத்திசைவு தேவைப்பட்டால், அமைப்புகளில் நீங்களே iCloud தரவு காப்பை இயக்குங்கள்; இயல்பாக முடக்கப்பட்டிருக்கும்.","trace.tagline":"ஒவ்வொரு பயணத்தையும் பதிவு செய்யுங்கள், கட்டுப்பாட்டையும் உங்கள் கையிலேயே வையுங்கள்.","trace.desc":"出行轨迹 TraceApp உங்கள் பாதை, தூரம், வேகம், பேஸ் ஆகியவற்றைப் பதிவு செய்ய உதவி, தரவை உள்ளூர்-முதன்மை முறையில் சேமிக்கிறது. கணக்கு தேவையில்லை, உள்ளே எந்த மூன்றாம் தரப்பு பகுப்பாய்வோ விளம்பர SDK-யோ இல்லை.","trace.feat.0":"பயணப் பாதையைப் பதிவு செய்து காட்டுங்கள்","trace.feat.1":"தூரம், வேகம், பேஸ் புள்ளிவிவரங்கள்","trace.feat.2":"தட மறுஇயக்கம் மற்றும் வரைபடக் காட்சிப்படுத்தல்","trace.feat.3":"விருப்பத் தேர்வு இயக்க-நிலை அடையாளம்","trace.feat.4":"சாதனத்தின் சாண்ட்பாக்ஸில் வரலாற்றைச் சேமியுங்கள்","trace.feat.5":"விருப்பத் தேர்வு iCloud சாதனங்களுக்கிடையே ஒத்திசைவு","trace.guide.0.t":"இருப்பிட அனுமதி அளியுங்கள்","trace.guide.0.b":'முதல் முறை பயன்படுத்தும்போது தேவைக்கேற்ப "App பயன்படுத்தும்போது" அல்லது "எப்போதும்" இருப்பிட அனுமதியைத் தேர்ந்தெடுங்கள்; அனுமதியை எப்போது வேண்டுமானாலும் கணினி அமைப்புகளில் மாற்றலாம்.',"trace.guide.1.t":"ஒரு பயணத்தைத் தொடங்குங்கள்","trace.guide.1.b":"பயன்பாட்டில் பதிவைத் தொடங்குங்கள், பாதை, தூரம், வேகம், பேஸ் தற்போதைய சாதனத்தில் சேமிக்கப்படும்.","trace.guide.2.t":"மறுஇயக்கம் மற்றும் ஒழுங்குபடுத்தல்","trace.guide.2.b":"வரலாற்றில் பாதையையும் புள்ளிவிவரங்களையும் பாருங்கள், தேவையற்ற பதிவுகளை நீக்குங்கள், அல்லது கணினிப் பகிர்வால் ஏற்றுமதி செய்யுங்கள் (பயன்பாடு வழங்கினால்).","trace.guide.3.t":"தேவைக்கேற்ப iCloud-ஐ இயக்குங்கள்","trace.guide.3.b":"உங்கள் சாதனங்களுக்கிடையே ஒத்திசைக்க வேண்டுமெனில் கணினியிலும் பயன்பாட்டிலும் நீங்களே iCloud-ஐ இயக்குங்கள்; டெவலப்பருக்கு உங்கள் iCloud சான்றுகளோ உள்ளடக்கமோ கிடைக்காது.","app.tab.overview":"தயாரிப்பு அறிமுகம்","app.tab.start":"தொடக்க வழிகாட்டி","app.tab.privacy":"தனியுரிமைக் கொள்கை","app.tab.terms":"பயனர் ஒப்பந்தம்","app.tab.support":"தொழில்நுட்ப ஆதரவு","app.cta.start":"பயன்படுத்தத் தொடங்குங்கள்","app.cta.readPrivacy":"தனியுரிமைக் கொள்கையைப் படியுங்கள்","app.shots":"ஸ்டோர் ஸ்கிரீன்ஷாட்கள்","app.faq":"அடிக்கடி கேட்கப்படும் கேள்விகள்","app.contactTitle":"எங்களைத் தொடர்பு கொள்ளுங்கள்","app.contactQ":"ஏதேனும் கேள்வி இருந்தால் தயவுசெய்து தொடர்பு கொள்ளுங்கள்:","app.supportContact":"இன்னும் உதவி தேவையா? தயவுசெய்து {email} க்கு மின்னஞ்சல் அனுப்புங்கள்.","app.getInStore":"{store} இல் {app} ஐப் பெறுங்கள்","app.legal.effective":"அமலுக்கு வரும் தேதி","app.legal.platform":"ஆதரிக்கப்படும் தளங்கள்","app.legal.appname":"ஆப்பின் பெயர்","app.footerSlogan":"தயாரிப்பு அறிமுகம் · தொடக்க வழிகாட்டி · தனியுரிமை மற்றும் ஆதரவு","tt.ui.headerSub":"GPS பாதைப் பதிவு · வழி மறுபார்வை · தனியுரிமை முதன்மை","tt.ui.ovTitle":"நேரத்தையும் இடத்தையும் இணைத்து உங்கள் சொந்தக் கதையை உருவாக்குங்கள்","tt.ui.privTitle":"பதிவுகள் உங்களுடையவை, தரவும் உங்களுடையதே","tt.ui.privBody":"கணக்கு தேவையில்லை, விளம்பரங்களோ மூன்றாம் தரப்பு கண்காணிப்போ இல்லை. பாதைகள் இயல்பாக இந்தச் சாதனத்திலேயே சேமிக்கப்படும்; iCloud காப்புப்பிரதி முற்றிலும் விருப்பமானது, அது உங்கள் Apple CloudKit தனிப்பட்ட தரவுத்தளத்திற்கு மட்டுமே செல்கிறது.","tt.ui.guideTitle":"உங்கள் முதல் பாதையிலிருந்து தொடங்குங்கள்","tt.ui.galleryTitle":"ஒவ்வொரு நாளின் வழியிலிருந்தும் காலத்தின் தடங்களைக் காணுங்கள்","tt.ui.desc.start":"இருப்பிட அனுமதி முதல் தினசரி பாதையைப் பார்ப்பது வரை, விரைவாகத் தொடங்குங்கள்.","tt.ui.desc.privacy":"இந்த ஆப்பில் இருப்பிடம், இயக்கம் மற்றும் iCloud காப்புப்பிரதி எவ்வாறு கையாளப்படுகின்றன என்பதை அறியுங்கள்.","tt.ui.desc.terms":"இந்த ஆப்பைப் பயன்படுத்தும் முன் தயவுசெய்து பயனர் ஒப்பந்தத்தைப் படியுங்கள்.","tt.ui.desc.support":"ஒவ்வொரு பயணத்தையும் எளிதாகப் பதிவுசெய்து மறுபார்வையிட நாங்கள் உங்களுக்கு உதவுகிறோம்.","tt.ui.faq.0.q":"TimeTrails எப்போதும் என் இருப்பிடத்தைக் கண்காணிக்குமா?","tt.ui.faq.0.a":"பதிவு உங்கள் கட்டுப்பாட்டில் உள்ளது, எப்போது வேண்டுமானாலும் இடைநிறுத்தலாம். கணினி இருப்பிடம் சாதனத்தில் பாதையைப் பதிவுசெய்யவே பயன்படுத்தப்படுகிறது, தரவு இயல்பாக சாதனத்திலேயே சேமிக்கப்படும்.","tt.ui.faq.1.q":"இருப்பிடம் பதிவாகவில்லையா?","tt.ui.faq.1.a":"“அமைப்புகள் → தனியுரிமை & பாதுகாப்பு → இருப்பிட சேவைகள்” இல் TimeTrails க்கு “எப்போதும்” என்பதைத் தேர்ந்தெடுத்து, “துல்லிய இருப்பிடம்” மற்றும் பின்னணி ஆப் புதுப்பிப்பை இயக்குங்கள்.","tt.ui.faq.2.q":"iCloud காப்புப்பிரதியை எவ்வாறு மீட்டெடுப்பது?","tt.ui.faq.2.a":"அதே Apple ID உடன், iCloud இயக்கத்தில் இருந்து இணையம் சரியாக இருக்கும்போது, அமைப்புகளின் “iCloud தரவு காப்புப்பிரதி” இல் மீட்டெடுக்கலாம் அல்லது கைமுறையாக ஒத்திசைக்கலாம்.","tt.ui.faq.3.q":"தரவை முழுமையாக எவ்வாறு அழிப்பது?","tt.ui.faq.3.a":"ஆப் அமைப்புகளில் உள்ளூர் தரவை அழிக்கலாம்; iCloud காப்புப்பிரதி இயக்கத்தில் இருந்தால், கிளவுட் நகலையும் நீக்குங்கள்.","trace.ui.headerSub":"வழிப் பதிவு · தரவு கட்டுப்பாட்டில்","trace.ui.ovTitle":"ஒவ்வொரு பயணத்திற்கும் பின்தொடரக்கூடிய தடம் இருக்கட்டும்","trace.ui.privTitle":"உள்ளூர் முதன்மை, தரவு கட்டுப்பாட்டில்","trace.ui.privBody":"கணக்கு தேவையில்லை, உள்ளமைந்த விளம்பரங்களோ மூன்றாம் தரப்பு புள்ளிவிவரங்களோ இல்லை. பாதைகள் இயல்பாக தற்போதைய சாதனத்திலேயே இருக்கும்; iCloud ஒத்திசைவு நீங்களே இயக்கும்போது மட்டுமே பயன்படுத்தப்படும்.","trace.ui.guideTitle":"முதல் பாதையிலிருந்து தொடங்குங்கள்","trace.ui.galleryTitle":"வழிகள், வரைபடங்கள் மற்றும் வரலாறு மறுபார்வை","trace.ui.desc.start":"இருப்பிட அனுமதி முதல் வழி மறுபார்வை வரை, விரைவாகத் தொடங்குங்கள்.","trace.ui.desc.privacy":"பாதைத் தரவு, iCloud மற்றும் கணினி அனுமதிகள் எவ்வாறு கையாளப்படுகின்றன என்பதை அறியுங்கள்.","trace.ui.desc.terms":"இந்த ஆப்பைப் பயன்படுத்தும் முன் தயவுசெய்து பயனர் ஒப்பந்தத்தைப் படியுங்கள்.","trace.ui.desc.support":"ஒவ்வொரு பயணத்தையும் எளிதாகப் பதிவுசெய்து நிர்வகிக்க நாங்கள் உங்களுக்கு உதவுகிறோம்.","trace.ui.faq.0.q":"இருப்பிட அனுமதியை எவ்வாறு சரிசெய்வது?","trace.ui.faq.0.a":"“அமைப்புகள் → தனியுரிமை & பாதுகாப்பு → இருப்பிட சேவைகள் → TraceApp” இல் “ஆப் பயன்படுத்தும்போது” அல்லது “எப்போதும்” என்பதைத் தேர்ந்தெடுங்கள், எப்போது வேண்டுமானாலும் அணைக்கலாம்.","trace.ui.faq.1.q":"தரவை எவ்வாறு நீக்குவது?","trace.ui.faq.1.a":"ஆப்பில் ஒரு அல்லது அனைத்துப் பதிவுகளையும் நீக்கலாம்; நிறுவல் நீக்கம் உள்ளூர் தரவை அழிக்கும். iCloud இயக்கத்தில் இருந்தால், ஒத்திசைக்கப்பட்ட நகலை iCloud இல் தனியாக நிர்வகிக்க வேண்டும்.","trace.ui.faq.2.q":"சிக்கலைப் புகாரளிக்கும்போது என்ன வழங்க வேண்டும்?","trace.ui.faq.2.a":"மீண்டும் நிகழ்த்தும் படிகள், எதிர்பார்த்த மற்றும் உண்மையான முடிவு, சாதன மாடல் மற்றும் கணினி பதிப்பு இணைக்க பரிந்துரைக்கப்படுகிறது; எளிதில் கண்டறிய ஸ்கிரீன்ஷாட்களையும் இணைக்கலாம்.","mem.ui.headerSub":"சிறப்பு நாட்கள் · பிறந்தநாட்கள் · கவுண்ட்டவுன்","mem.ui.ovTitle":"பதிவுசெய்யத் தகுந்த ஒவ்வொரு வகையான முக்கியத் தருணத்திற்கும்","mem.ui.privTitle":"வசதிக்கு முன் தனியுரிமை","mem.ui.priv.ios":"கணக்கு இல்லை, விளம்பரங்கள் இல்லை, மூன்றாம் தரப்பு கண்காணிப்பு இல்லை; ஒத்திசைவு இயக்கத்தில் இருந்தால் அது உங்கள் iCloud தனிப்பட்ட தரவுத்தளத்திற்கு மட்டுமே செல்கிறது.","mem.ui.priv.hm":"கணக்கு இல்லை, இணைய இணைப்பு இல்லை, கிளவுட் காப்புப்பிரதி இல்லை; உங்கள் பதிவுகள் தற்போதைய சாதனத்தில் மட்டுமே சேமிக்கப்படும்.","mem.ui.guideTitle":"முதல் பதிவிலிருந்து தொடங்குங்கள்","mem.ui.galleryTitle":"{app} இன் உண்மையான இடைமுகத்தைப் பாருங்கள்","mem.ui.storeHint":"இந்த ஆப்பைப் பெற {store} இல் “{app}” ஐத் தேடுங்கள்.","mem.ui.desc.start":"முதல் உருவாக்கம் முதல் அறிவிப்பு அனுமதி வரை, {app} ஐப் பயன்படுத்த விரைவாகத் தொடங்குங்கள்.","mem.ui.desc.privacy":"நீங்கள் பயன்படுத்தும் தளத்திற்கு ஏற்ப பொருந்தும் {app} தனியுரிமைக் கொள்கையைப் படியுங்கள்.","mem.ui.desc.terms":"{app} ஐப் பயன்படுத்தும் முன் தயவுசெய்து இந்தப் பயனர் ஒப்பந்தத்தைப் படியுங்கள்.","mem.ui.desc.support":"{app} ஐ எளிதாகப் பயன்படுத்த நாங்கள் உங்களுக்கு உதவுகிறோம்.","mem.ui.faq.0.q":"தரவு பிற சாதனங்களுக்கு ஒத்திசைக்கப்படுமா?","mem.ui.faq.0.a.ios":"iCloud இல் உள்நுழைந்து ஒத்திசைவை இயக்கிய பிறகு, தரவு உங்கள் iCloud தனிப்பட்ட தரவுத்தளம் வழியாக iPhone, iPad மற்றும் Apple Watch இடையே ஒத்திசைக்கப்படும்.","mem.ui.faq.0.a.hm":"இல்லை. இந்தப் பதிப்பு இணையத்துடன் இணையாது, கிளவுட் ஒத்திசைவை வழங்காது, தரவு தற்போதைய சாதனத்தில் மட்டுமே இருக்கும்.","mem.ui.faq.1.q":"தரவை எவ்வாறு நீக்குவது?","mem.ui.faq.1.a.ios":"ஆப்பில் பதிவுகளை நீக்கலாம்; ஆப்பை நிறுவல் நீக்கம் செய்தால் உள்ளூர் தரவு அழிக்கப்படும், iCloud தரவை கணினியின் “அமைப்புகள் → iCloud” இல் நிர்வகிக்கலாம்.","mem.ui.faq.1.a.hm":"ஆப்பில் பதிவுகளை நீக்கி மறுசுழற்சிப் பெட்டியை காலி செய்யலாம்; ஆப்பை நிறுவல் நீக்கம் செய்தால் அனைத்து உள்ளூர் தரவும் அழிக்கப்படும்.","mem.ui.faq.2.q":"நினைவூட்டல் தோன்றவில்லை என்றால் என்ன செய்வது?","mem.ui.faq.2.a":"பதிவுக்கு நினைவூட்டல் அமைக்கப்பட்டுள்ளதா என்பதையும், கணினி அமைப்புகளில் இந்த ஆப்பிற்கு அறிவிப்பு அனுப்ப அனுமதி உள்ளதா என்பதையும் உறுதிசெய்யுங்கள். அறிவிப்புகளை அணைப்பது நினைவூட்டல்களை மட்டுமே பாதிக்கும், பதிவுகளை அல்ல.","mem.ui.pc.title":"முக்கியமான நாட்களை உங்களுக்கு ஏற்ற சாதனத்தில் வைத்திருங்கள்.","mem.ui.pc.desc":"நீங்கள் பயன்படுத்தும் தளத்தைத் தேர்ந்தெடுங்கள். இரு பதிப்புகளும் உள்ளூர் தரவு மற்றும் மூன்றாம் தரப்பு கண்காணிப்பு இல்லாத கொள்கையில் இயங்குகின்றன, ஆனால் ஒத்திசைவுத் திறன், ஆப்பின் பெயர் மற்றும் பொருந்தும் ஒப்பந்தம் வேறுபடுகின்றன.","mem.ui.pc.ios.desc":"உள்ளூர் நினைவூட்டல், விட்ஜெட், Apple Watch மற்றும் விருப்ப iCloud தனிப்பட்ட ஒத்திசைவை ஆதரிக்கிறது.","mem.ui.pc.ios.cta":"iOS பதிப்பைப் பார்க்கவும்","mem.ui.pc.hm.desc":"முழுமையான உள்ளூர் பதிப்பு: இணையம் இல்லை, கிளவுட் ஒத்திசைவு இல்லை, தரவு சாதனத்தின் ஆப் சாண்ட்பாக்ஸில் மட்டுமே இருக்கும்.","mem.ui.pc.hm.cta":"HarmonyOS பதிப்பைப் பார்க்கவும்"};export{e as default};
